import React from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { 
  LayoutDashboard, 
  BookOpen, 
  AlertCircle, 
  LogOut, 
  Gamepad2, // 👈 YANGI: O'yin ikonkasi
  User      // 👈 YANGI: Profil/Sozlamalar uchun (Studentga)
} from 'lucide-react'; 
import { auth } from '../firebase'; 
import { signOut } from 'firebase/auth'; 

// 🔥 role propini qabul qilamiz
const MobileNavbar = ({ role }) => {
  const location = useLocation();
  const navigate = useNavigate();

  const handleLogout = async () => {
    if (window.confirm("Tizimdan chiqmoqchimisiz?")) {
      await signOut(auth);
      navigate('/login');
    }
  };

  // 1. O'QITUVCHI MENYUSI (Eski kod o'zgarishsiz)
  const teacherNavItems = [
    { 
      path: '/', 
      icon: <LayoutDashboard size={20} />, 
      label: 'Guruhlar' 
    }, 
    { 
      path: '/assignments', 
      icon: <BookOpen size={20} />, 
      label: 'Vazifalar' 
    },
    { 
      path: '/debtors', 
      icon: <AlertCircle size={20} />, 
      label: 'Qarzdorlar' 
    },
  ];

  // 2. O'QUVCHI MENYUSI (Yangi)
  const studentNavItems = [
    { 
      path: '/', 
      icon: <LayoutDashboard size={20} />, 
      label: 'Asosiy' 
    },
    { 
      path: '/games',  // 👈 Bu yerda GameHub ga yo'naltiradi
      icon: <Gamepad2 size={20} />, 
      label: 'O\'yinlar' 
    },
    { 
      path: '/settings', 
      icon: <User size={20} />, 
      label: 'Profil' 
    },
  ];

  // Rolga qarab kerakli menyuni tanlaymiz
  const navItems = role === 'student' ? studentNavItems : teacherNavItems;

  return (
    <div className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-md border-t border-slate-200 px-4 py-2 md:hidden z-50 pb-safe shadow-[0_-4px_6px_-1px_rgba(0,0,0,0.05)]">
      <div className="flex justify-between items-center max-w-sm mx-auto">
        
        {navItems.map((item) => {
          const isActive = location.pathname === item.path;
          
          // 🔥 Maxsus ranglar logikasi
          const isDebtorTab = item.path === '/debtors';
          const isGameTab = item.path === '/games';

          // Qarzdorlar -> Qizil, O'yinlar -> Binafsha, Boshqalar -> Indigo
          let activeBg = 'bg-indigo-600 shadow-indigo-200';
          let activeText = 'text-indigo-600';

          if (isDebtorTab) {
            activeBg = 'bg-red-500 shadow-red-200';
            activeText = 'text-red-500';
          } else if (isGameTab) {
            activeBg = 'bg-purple-600 shadow-purple-200'; // O'yinlar uchun chiroyli rang
            activeText = 'text-purple-600';
          }

          return (
            <Link 
              key={item.path} 
              to={item.path} 
              className="flex flex-col items-center gap-1 p-2 min-w-[64px]"
            >
              <div className={`p-1.5 rounded-xl transition-all duration-300 ${isActive ? `${activeBg} text-white shadow-lg translate-y-[-4px]` : 'text-slate-400'}`}>
                {item.icon}
              </div>
              <span className={`text-[9px] font-bold tracking-wide ${isActive ? activeText : 'text-slate-400'}`}>
                {item.label}
              </span>
            </Link>
          );
        })}

        {/* LOGOUT TUGMASI */}
        <button 
          onClick={handleLogout}
          className="flex flex-col items-center gap-1 p-2 min-w-[64px] group"
        >
          <div className="p-1.5 rounded-xl text-slate-400 group-hover:bg-red-50 group-hover:text-red-500 transition-all">
            <LogOut size={20} />
          </div>
          <span className="text-[9px] font-bold text-slate-400 group-hover:text-red-500 tracking-wide">
            Chiqish
          </span>
        </button>
      </div>
    </div>
  );
};

export default MobileNavbar;